        [(DAV, DAV_CAPABILITIES), (header::ALLOW, DAV_ALLOW)],
    )
        .into_response()
}

fn method_not_allowed() -> Response {
    (StatusCode::METHOD_NOT_ALLOWED, [(header::ALLOW, DAV_ALLOW)]).into_response()
}

