async fn t16_categories_survive_unrelated_edit() {
    let (temp_dir, pool, accounts, _user_id, password, principal_id, calendar_id) =
        setup_create().await;

    let uri = format!("/dav/calendars/{principal_id}/{calendar_id}/t16-survive.ics");
