    assert_eq!(event.categories, vec!["Work".to_owned(), "Personal".to_owned()]);
    assert_eq!(event.url.as_deref(), Some("https://example.test/event"));
    assert_eq!(event.transp.as_deref(), Some("OPAQUE"));

